"""
Comprehensive test for empty security objects and edge cases
"""

from openapi3 import OpenAPI

def test_empty_security_in_global():
    """Test empty security object in global security"""
    schema = {
        "openapi": "3.0.3",
        "info": {"title": "Test", "version": "1.0.0"},
        "security": [{}],  # Global empty security
        "paths": {
            "/test": {
                "get": {
                    "responses": {"200": {"description": "OK"}}
                }
            }
        }
    }

    api = OpenAPI(schema)
    # Should inherit global security
    security = api.paths['/test'].get.security
    assert len(security) == 1
    assert security[0].name is None
    assert security[0].types == []
    assert security[0].__getstate__() == {}
    print("✓ Global empty security test passed")

def test_mixed_security_requirements():
    """Test mix of regular and empty security requirements"""
    schema = {
        "openapi": "3.0.3",
        "info": {"title": "Test", "version": "1.0.0"},
        "paths": {
            "/test": {
                "get": {
                    "security": [
                        {"oauth2": ["read", "write"]},
                        {"apiKey": []},
                        {},  # No security
                        {"basicAuth": []}
                    ],
                    "responses": {"200": {"description": "OK"}}
                }
            }
        },
        "components": {
            "securitySchemes": {
                "oauth2": {
                    "type": "oauth2",
                    "flows": {}
                },
                "apiKey": {
                    "type": "apiKey",
                    "in": "header",
                    "name": "X-API-Key"
                },
                "basicAuth": {
                    "type": "http",
                    "scheme": "basic"
                }
            }
        }
    }

    api = OpenAPI(schema)
    security = api.paths['/test'].get.security
    assert len(security) == 4

    # Check OAuth2 requirement
    assert security[0].name == "oauth2"
    assert security[0].types == ["read", "write"]
    assert security[0].__getstate__() == {"oauth2": ["read", "write"]}

    # Check API Key requirement
    assert security[1].name == "apiKey"
    assert security[1].types == []
    assert security[1].__getstate__() == {"apiKey": []}

    # Check empty requirement
    assert security[2].name is None
    assert security[2].types == []
    assert security[2].__getstate__() == {}

    # Check Basic Auth requirement
    assert security[3].name == "basicAuth"
    assert security[3].types == []
    assert security[3].__getstate__() == {"basicAuth": []}

    print("✓ Mixed security requirements test passed")

def test_only_empty_security():
    """Test operation with only empty security"""
    schema = {
        "openapi": "3.0.3",
        "info": {"title": "Test", "version": "1.0.0"},
        "paths": {
            "/public": {
                "get": {
                    "security": [{}],  # Explicitly no security
                    "responses": {"200": {"description": "OK"}}
                }
            }
        }
    }

    api = OpenAPI(schema)
    security = api.paths['/public'].get.security
    assert len(security) == 1
    assert security[0].name is None
    assert security[0].types == []
    assert security[0].__getstate__() == {}
    print("✓ Only empty security test passed")

def test_multiple_empty_security():
    """Test multiple empty security objects"""
    schema = {
        "openapi": "3.0.3",
        "info": {"title": "Test", "version": "1.0.0"},
        "paths": {
            "/weird": {
                "get": {
                    "security": [{}, {}, {}],  # Multiple empty securities
                    "responses": {"200": {"description": "OK"}}
                }
            }
        }
    }

    api = OpenAPI(schema)
    security = api.paths['/weird'].get.security
    assert len(security) == 3
    for sec in security:
        assert sec.name is None
        assert sec.types == []
        assert sec.__getstate__() == {}
    print("✓ Multiple empty security test passed")

def test_invalid_security_still_fails():
    """Test that invalid security objects still fail appropriately"""
    # This should still fail - object with non-list value
    schema = {
        "openapi": "3.0.3",
        "info": {"title": "Test", "version": "1.0.0"},
        "paths": {
            "/test": {
                "get": {
                    "security": [{"invalid": "not_a_list"}],
                    "responses": {"200": {"description": "OK"}}
                }
            }
        }
    }

    try:
        OpenAPI(schema)
        assert False, "Should have failed"
    except Exception as e:
        assert "Could not parse" in str(e)
        print("✓ Invalid security still fails correctly")

if __name__ == "__main__":
